fn main() { let stops: Vec<(&str, u64, u64)> = vec![("中和國民運動中心1", 44461, 44593), ("中和國民運動中心2", 44641, 45241)]; let off_time: u64 = 44614; let grace_period: u64 = 600; let mut alight_stop_idx = None; let mut p2 = 0; while p2 < stops.len() { if stops[p2].2 >= off_time { alight_stop_idx = Some(p2); break; } p2 += 1; } println!("Matched stop index: {:?}", alight_stop_idx); if let Some(idx) = alight_stop_idx { let diff = stops[idx].2.saturating_sub(off_time); println!("Grace check: {} - {} = {}", stops[idx].2, off_time, diff); if diff > grace_period { println!("Failed grace period!"); alight_stop_idx = None; } } println!("Final alight stop: {:?}", alight_stop_idx); }
